pub fn point_cloud_support_point_id(dir: Vector, points: &[Vector]) -> usize {
    let mut best_pt = 0;
    let mut best_dot = points[0].dot(dir);

    for (i, p) in points.iter().enumerate().skip(1) {
        let dot = p.dot(dir);

        if dot > best_dot {
            best_dot = dot;
            best_pt = i;
        }
    }

    best_pt
}

